UPDATE task_step
SET status      = 'PASSED',
    message     = #{message},
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}
  AND stage = #{stage}

UPDATE task_step
SET status      = 'FAILED',
    message     = #{message},
    finished_at = #{finishedAt}
WHERE task_id = #{taskId}
  AND stage = #{stage}
